import { dirname } from 'path';
import { fileURLToPath } from 'url';
import { FlatCompat } from '@eslint/eslintrc';

// ESLint 9 flat config. eslint-config-next still ships in the old "extends"
// format, so FlatCompat translates it — this is the shape Next's own codemod
// produces, and it replaces `next lint`, which is removed in Next 16.
const compat = new FlatCompat({ baseDirectory: dirname(fileURLToPath(import.meta.url)) });

export default [
  {
    // next-env.d.ts is generated by Next on every build; editing it is pointless.
    ignores: ['.next/**', 'node_modules/**', 'public/**', 'prisma/migrations/**', 'next-env.d.ts'],
  },

  ...compat.extends('next/core-web-vitals', 'next/typescript'),

  {
    rules: {
      // The codebase leans on `any` at trust boundaries — parsed request bodies
      // and caught errors — where a real type would be a lie. Flagged, not fatal,
      // so the signal stays visible without blocking a deploy.
      '@typescript-eslint/no-explicit-any': 'warn',

      // Unused code is usually a leftover from a refactor, but an argument named
      // with a leading underscore is a deliberate "I know, I am not using it".
      '@typescript-eslint/no-unused-vars': [
        'warn',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_' },
      ],

      // Quotes and apostrophes inside copy are intentional typography. Escaping
      // them to &quot; buys nothing a reader can see and costs every reader of
      // the source, so the rule is off rather than worked around case by case.
      'react/no-unescaped-entities': 'off',
    },
  },

  {
    // Error boundaries recover by reloading the document. <Link> would navigate
    // on the client and keep the broken React tree alive, and in global-error
    // the root layout itself has failed, so client routing may not work at all.
    // The plain <a> is the fix here, not the mistake.
    files: ['app/error.tsx', 'app/global-error.tsx', 'app/not-found.tsx'],
    rules: { '@next/next/no-html-link-for-pages': 'off' },
  },
];
